INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT146-S1-Q3$batch06$, 146, 1, 3, $batch06$Method$batch06$, $batch06$Flynn: Allowing people to collect large damage awards when they successfully sue corporations that produce dangerous products clearly benefits consumers, since the possibility of large awards gives corporations a strong incentive to reduce safety risks associated with their products. Garcia: Without sensible limits, damage awards can be so high that corporations are destroyed. As a result, employees lose their jobs and the productivity of the corporation is lost. This harms the economy and thus harms consumers.$batch06$, $batch06$Garcia responds to Flynn’s argument by$batch06$, $batch06$A$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=146 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$arguing that the policy supported in Flynn’s argument could have undesirable consequences$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$providing evidence that undermines one of the premises of Flynn’s argument$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$comparing Flynn’s argument to an obviously flawed argument that has the same logical structure$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$contending that Flynn’s argument could be used to support a policy that is inconsistent with the policy that Flynn advocates$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$providing an alternative explanation for a situation described in Flynn’s argument$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Garcia, implied) Unlimited damage awards can hurt consumers.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Huge awards can destroy corporations, costing jobs and productivity, which harms the economy and so harms consumers.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Flynn says large awards help consumers by pushing companies toward safety. Garcia does not deny that incentive. He traces another chain: awards too large destroy companies, and that comes back around to hurt the same consumers. The policy has a downside Flynn ignored.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Arguing Flynn's policy could have undesirable consequences.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The policy is allowing large awards without limits. The undesirable consequence is ruined companies and the harm that spreads to consumers.$batch06$), ($batch06$B$batch06$, $batch06$Garcia does not deny that large awards give companies an incentive to be safer. Flynn's premise is left standing.$batch06$), ($batch06$C$batch06$, $batch06$No flawed parallel argument is offered.$batch06$), ($batch06$D$batch06$, $batch06$Garcia does not show Flynn's argument supporting some inconsistent policy.$batch06$), ($batch06$E$batch06$, $batch06$No situation in Flynn's argument gets a new explanation.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT146-S1-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
